// Android draws the notification small icon from the alpha channel only: without a dedicated icon the
// expo-notifications plugin emits no `default_notification_icon` and the opaque launcher icon shows as a
// solid blob. The icon is generated by scripts/build-icons.mjs.
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, it } from 'node:test';

// tsx runs the tests as CommonJS; the project's types do not declare Node's module globals.
declare const __dirname: string;
const root = join(__dirname, '..');

type PluginEntry = string | [string, Record<string, unknown>];

function notificationsPluginOptions(): Record<string, unknown> {
  const config = JSON.parse(readFileSync(join(root, 'app.json'), 'utf8')) as { expo: { plugins: PluginEntry[] } };
  const entry = config.expo.plugins.find((plugin) => Array.isArray(plugin) && plugin[0] === 'expo-notifications');
  assert.ok(Array.isArray(entry), 'expo-notifications is configured with options');
  return entry[1];
}

describe('Android notification icon', () => {
  it('the expo-notifications plugin points at a 96×96 RGBA png that exists', () => {
    const icon = notificationsPluginOptions().icon;
    assert.equal(typeof icon, 'string');
    const path = join(root, icon as string);
    assert.ok(existsSync(path), `${icon} exists`);
    const png = readFileSync(path);
    assert.equal(png.subarray(1, 4).toString('ascii'), 'PNG');
    assert.equal(png.subarray(12, 16).toString('ascii'), 'IHDR');
    assert.equal(png.readUInt32BE(16), 96, 'width');
    assert.equal(png.readUInt32BE(20), 96, 'height');
    // Colour type 6 = RGBA: the glyph is drawn from the alpha channel.
    assert.equal(png[25], 6, 'has an alpha channel');
  });
});
